import { useState, useEffect, useCallback, createContext, useContext } from "react";
import { loadData, saveData } from "./firebase.js";

const NempaLogo = ({ size = 44 }) => (
  <svg width={size} height={size * 1.2} viewBox="0 0 100 120">
    <polygon points="50,5 90,28 90,50 50,73 10,50 10,28" fill="#F5A623" opacity=".9"/>
    <polygon points="50,30 90,53 90,75 50,98 10,75 10,53" fill="#C0392B" opacity=".85"/>
    <polygon points="10,28 50,5 50,30 10,53" fill="#F5C623" opacity=".7"/>
    <polygon points="10,53 50,30 50,73 10,75" fill="#2E86DE" opacity=".85"/>
    <polygon points="50,30 90,28 90,53 50,73" fill="#E74C3C" opacity=".7"/>
    <text x="50" y="115" textAnchor="middle" fill="white" fontFamily="'Outfit',sans-serif" fontWeight="800" fontSize="18">NEMPA</text>
  </svg>
);

const THEMES = {
  dark: { bg:"#0D1117",card:"#161B22",border:"#30363D",text:"#E6EDF3",textMuted:"#8B949E",yellow:"#F5A623",red:"#C0392B",blue:"#2E86DE",success:"#2ECC71",purple:"#9B59B6",orange:"#E67E22",headerBg:"linear-gradient(135deg,#161B22,#0D1117)" },
  light: { bg:"#F0F2F5",card:"#FFFFFF",border:"#D0D7DE",text:"#1F2328",textMuted:"#656D76",yellow:"#D4940E",red:"#C0392B",blue:"#2E86DE",success:"#1E8449",purple:"#7D3C98",orange:"#CA6F1E",headerBg:"linear-gradient(135deg,#FFFFFF,#F0F2F5)" },
};
const ThemeCtx = createContext(THEMES.dark);
const UserCtx = createContext(null);

const ALL_TABS=["Dashboard","Ações","Relatórios","Comparativo","Calendário","Associados","Parceiros","Documentos","Leads","Usuários"];
const ALL_ICONS=["📊","⚡","📝","📈","📅","🎫","🤝","📁","🎯","🔐"];
const PERIOD_OPTIONS=[{label:"30d",days:30},{label:"90d",days:90},{label:"180d",days:180},{label:"365d",days:365}];

function gid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function fc(v){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(v)}
function fd(d){try{return new Date(d+"T12:00:00").toLocaleDateString("pt-BR")}catch{return d}}
function today(){return new Date().toISOString().slice(0,10)}
function daysAgo(n){const d=new Date();d.setDate(d.getDate()-n);return d.toISOString().slice(0,10)}
function curDate(){const d=new Date();const ds=["Domingo","Segunda-feira","Terça-feira","Quarta-feira","Quinta-feira","Sexta-feira","Sábado"];const ms=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];return ds[d.getDay()]+", "+d.getDate()+" de "+ms[d.getMonth()]+" de "+d.getFullYear()}
function hashPw(pw){let h=0;for(let i=0;i<pw.length;i++){h=((h<<5)-h)+pw.charCodeAt(i);h|=0}return"h"+Math.abs(h).toString(36)}
function canEdit(user){return user?.role==="admin"||user?.role==="editor"}
function isApoiador(user){return user?.role==="apoiador"}

function getVisibleTabs(user){
  if(!user) return [];
  if(user.role==="admin") return ALL_TABS;
  if(user.role==="apoiador") return ["Dashboard","Ações","Relatórios","Comparativo"];
  return ALL_TABS.filter(t=>t!=="Usuários");
}
function getVisibleIcons(user){return getVisibleTabs(user).map(t=>{const idx=ALL_TABS.indexOf(t);return ALL_ICONS[idx]})}

const DEF={acoes:[],parceiros:[],associados:[],reports:[],eventos:[],documentos:[],leads:[]};
const DEF_USERS=[{id:"admin",nome:"Administrador",login:"admin",senha:hashPw("nempa2026"),role:"admin"}];
const UF_OPTS=[{value:"",label:"UF"},...["AC","AL","AP","AM","BA","CE","DF","ES","GO","MA","MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN","RS","RO","RR","SC","SP","SE","TO"].map(u=>({value:u,label:u}))];
const ROLE_LABELS={admin:"Administrador",editor:"Editor",leitor:"Leitor",apoiador:"Apoiador"};
const ROLE_COLORS_FN=(T)=>({admin:T.yellow,editor:T.blue,leitor:T.textMuted,apoiador:T.purple});
const ROLE_DESC={admin:"Acesso total + gestão de usuários",editor:"Presidente/Executivo — vê e edita tudo",leitor:"Diretores/membros — vê tudo, sem editar",apoiador:"Empresas apoiadoras — vê Ações, Relatórios e Comparativo"};
const INICIATIVA_OPTS=[{value:"Iniciativa própria",label:"Iniciativa própria"},{value:"Iniciativa de terceiros",label:"Iniciativa de terceiros"}];

const Badge=({color,children})=>(<span style={{background:color+"22",color,padding:"2px 10px",borderRadius:20,fontSize:12,fontWeight:600,whiteSpace:"nowrap"}}>{children}</span>);
const StatCard=({icon,label,value,sub,accent})=>{const T=useContext(ThemeCtx);return(<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:"20px 18px",flex:"1 1 170px",minWidth:160,position:"relative",overflow:"hidden"}}><div style={{position:"absolute",top:0,left:0,width:"100%",height:3,background:"linear-gradient(90deg,"+accent+",transparent)"}}/><div style={{fontSize:26,marginBottom:4}}>{icon}</div><div style={{fontSize:24,fontWeight:800,color:T.text}}>{value}</div><div style={{fontSize:12,color:T.textMuted,marginTop:2}}>{label}</div>{sub&&<div style={{fontSize:11,color:accent,marginTop:4}}>{sub}</div>}</div>)};
const Btn=({children,onClick,accent,small,outline,disabled,style:sx})=>{const T=useContext(ThemeCtx);const c=accent||T.yellow;return (<button disabled={disabled} onClick={onClick} style={{background:outline?"transparent":c,color:outline?c:"#000",border:outline?"1px solid "+c:"none",borderRadius:10,padding:small?"6px 12px":"10px 20px",fontSize:small?12:14,fontWeight:700,cursor:disabled?"not-allowed":"pointer",fontFamily:"'Outfit',sans-serif",opacity:disabled?.5:1,...sx}}>{children}</button>)};
const Inp=({label,...p})=>{const T=useContext(ThemeCtx);return(<div style={{display:"flex",flexDirection:"column",gap:4,flex:1}}>{label&&<label style={{fontSize:12,color:T.textMuted,fontWeight:600}}>{label}</label>}<input {...p} style={{background:T.bg,border:"1px solid "+T.border,borderRadius:8,padding:"9px 12px",color:T.text,fontSize:14,fontFamily:"'Outfit',sans-serif",outline:"none",width:"100%",boxSizing:"border-box",...(p.style||{})}}/></div>)};
const Txt=({label,...p})=>{const T=useContext(ThemeCtx);return(<div style={{display:"flex",flexDirection:"column",gap:4}}>{label&&<label style={{fontSize:12,color:T.textMuted,fontWeight:600}}>{label}</label>}<textarea {...p} style={{background:T.bg,border:"1px solid "+T.border,borderRadius:8,padding:"9px 12px",color:T.text,fontSize:14,fontFamily:"'Outfit',sans-serif",outline:"none",resize:"vertical",minHeight:70,width:"100%",boxSizing:"border-box"}}/></div>)};
const Sel=({label,options,...p})=>{const T=useContext(ThemeCtx);return(<div style={{display:"flex",flexDirection:"column",gap:4,flex:1}}>{label&&<label style={{fontSize:12,color:T.textMuted,fontWeight:600}}>{label}</label>}<select {...p} style={{background:T.bg,border:"1px solid "+T.border,borderRadius:8,padding:"9px 12px",color:T.text,fontSize:14,fontFamily:"'Outfit',sans-serif",outline:"none"}}>{options.map(o=>(<option key={o.value} value={o.value}>{o.label}</option>))}</select></div>)};
const Modal=({open,onClose,title,children})=>{const T=useContext(ThemeCtx);if(!open)return null;return(<div style={{position:"fixed",inset:0,zIndex:1000,background:"rgba(0,0,0,.65)",display:"flex",alignItems:"center",justifyContent:"center",padding:16}} onClick={onClose}><div onClick={e=>e.stopPropagation()} style={{background:T.card,border:"1px solid "+T.border,borderRadius:20,padding:26,width:"100%",maxWidth:540,maxHeight:"85vh",overflowY:"auto"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}><h3 style={{margin:0,color:T.text,fontSize:19}}>{title}</h3><span onClick={onClose} style={{cursor:"pointer",color:T.textMuted,fontSize:20}}>✕</span></div>{children}</div></div>)};
const ReadOnlyBanner=()=>{const T=useContext(ThemeCtx);return(<div style={{background:T.yellow+"15",border:"1px solid "+T.yellow+"44",borderRadius:10,padding:"8px 14px",marginBottom:14,fontSize:13,color:T.yellow,fontWeight:600}}>👁️ Modo leitura — sem permissão para editar.</div>)};

function filterByPeriod(items,days){const c=daysAgo(days);return items.filter(i=>i.data>=c)}
function filterByRange(items,start,end){return items.filter(i=>i.data>=start&&i.data<=end)}
function computeKpis(data,days){const a=days?filterByPeriod(data.acoes||[],days):(data.acoes||[]);const assoc=Array.isArray(data.associados)?data.associados:[];const parcs=Array.isArray(data.parceiros)?data.parceiros:[];const leads=Array.isArray(data.leads)?data.leads:[];const externas=a.filter(x=>x.iniciativa==="Iniciativa de terceiros").length;return{totalAcoes:a.length,pessoasImpactadas:a.reduce((s,x)=>s+(x.pessoas||0),0),custoTotal:a.reduce((s,x)=>s+(x.custo||0),0),horasTotais:a.reduce((s,x)=>s+(x.horas||0),0),externas,parceiros:parcs.filter(p=>p.status==="Ativo").length,associados:assoc.length,leads:leads.length,cotaAssociados:assoc.reduce((s,x)=>s+(Number(x.cota)||0),0),cotaParceiros:parcs.reduce((s,x)=>s+(Number(x.cotaApoio)||0),0),acoes:a}}
function computeRange(data,start,end){const a=filterByRange(data.acoes||[],start,end);const externas=a.filter(x=>x.iniciativa==="Iniciativa de terceiros").length;return{totalAcoes:a.length,pessoasImpactadas:a.reduce((s,x)=>s+(x.pessoas||0),0),custoTotal:a.reduce((s,x)=>s+(x.custo||0),0),horasTotais:a.reduce((s,x)=>s+(x.horas||0),0),externas}}
function monthly(data,days){const c=daysAgo(days);const a=(data.acoes||[]).filter(x=>x.data>=c);const map={};const M=["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];a.forEach(x=>{const d=new Date(x.data+"T12:00:00");const k=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");const l=M[d.getMonth()]+"/"+d.getFullYear();if(!map[k])map[k]={key:k,label:l,acoes:0,pessoas:0,custo:0,horas:0};map[k].acoes++;map[k].pessoas+=x.pessoas||0;map[k].custo+=x.custo||0;map[k].horas+=x.horas||0});return Object.values(map).sort((a,b)=>a.key.localeCompare(b.key))}

function LoginScreen({onLogin,users}){const[login,setLogin]=useState("");const[senha,setSenha]=useState("");const[err,setErr]=useState("");const[show,setShow]=useState(false);const submit=()=>{setErr("");const u=users.find(u=>u.login===login.trim());if(!u){setErr("Usuário não encontrado.");return}if(u.senha!==hashPw(senha)){setErr("Senha incorreta.");return}onLogin(u)};const keyDown=e=>{if(e.key==="Enter")submit()};return(<div style={{minHeight:"100vh",background:"#0D1117",display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Outfit',sans-serif",padding:20}}><div style={{width:"100%",maxWidth:400,textAlign:"center"}}><div style={{display:"flex",justifyContent:"center",marginBottom:10}}><NempaLogo size={80}/></div><div style={{fontSize:11,color:"#8B949E",letterSpacing:1,marginBottom:30}}>NÚCLEO DE EMPREENDEDORISMO DE POUSO ALEGRE</div><div style={{background:"#161B22",border:"1px solid #30363D",borderRadius:20,padding:"32px 28px"}}><h2 style={{color:"#E6EDF3",margin:"0 0 6px",fontSize:22,fontWeight:800}}>Acesso ao Hub</h2><p style={{color:"#8B949E",fontSize:13,margin:"0 0 24px"}}>Entre com suas credenciais</p><div style={{display:"flex",flexDirection:"column",gap:14,textAlign:"left"}}><div><label style={{fontSize:12,color:"#8B949E",fontWeight:600,display:"block",marginBottom:4}}>Usuário</label><input value={login} onChange={e=>setLogin(e.target.value)} onKeyDown={keyDown} placeholder="Digite seu login" style={{background:"#0D1117",border:"1px solid #30363D",borderRadius:10,padding:"12px 14px",color:"#E6EDF3",fontSize:15,fontFamily:"'Outfit',sans-serif",outline:"none",width:"100%",boxSizing:"border-box"}}/></div><div><label style={{fontSize:12,color:"#8B949E",fontWeight:600,display:"block",marginBottom:4}}>Senha</label><div style={{position:"relative"}}><input value={senha} onChange={e=>setSenha(e.target.value)} onKeyDown={keyDown} type={show?"text":"password"} placeholder="Digite sua senha" style={{background:"#0D1117",border:"1px solid #30363D",borderRadius:10,padding:"12px 14px",color:"#E6EDF3",fontSize:15,fontFamily:"'Outfit',sans-serif",outline:"none",width:"100%",boxSizing:"border-box",paddingRight:44}}/><span onClick={()=>setShow(!show)} style={{position:"absolute",right:12,top:"50%",transform:"translateY(-50%)",cursor:"pointer",fontSize:18,color:"#8B949E"}}>{show?"🙈":"👁️"}</span></div></div></div>{err&&<div style={{background:"#C0392B22",color:"#E74C3C",padding:"8px 12px",borderRadius:8,fontSize:13,marginTop:14,fontWeight:600}}>{err}</div>}<button onClick={submit} style={{width:"100%",background:"#F5A623",color:"#000",border:"none",borderRadius:12,padding:"13px 0",fontSize:16,fontWeight:800,cursor:"pointer",fontFamily:"'Outfit',sans-serif",marginTop:20}}>Entrar</button></div><div style={{marginTop:20,fontSize:11,color:"#8B949E"}}>Acesso restrito · NEMPA Hub v4.0</div></div></div>)}

export default function App(){const[user,setUser]=useState(null);const[users,setUsers]=useState(DEF_USERS);const[tab,setTab]=useState(0);const[data,setData]=useState(DEF);const[loading,setLoading]=useState(true);const[modal,setModal]=useState(null);const openModal=(type,editItem)=>{if(!canEdit(user))return;setModal({type,edit:editItem||null})};const closeModal=()=>setModal(null);const[period,setPeriod]=useState(null);const[theme,setTheme]=useState("dark");const T=THEMES[theme];
useEffect(()=>{(async()=>{const d=await loadData("data",null);if(d){const m={...DEF,...d};["associados","parceiros","reports","eventos","documentos","leads","acoes"].forEach(k=>{if(!Array.isArray(m[k]))m[k]=[]});setData(m)}const u=await loadData("users",null);if(u&&u.length>0)setUsers(u);setLoading(false)})()},[]);
const up=useCallback(fn=>{setData(prev=>{const next=typeof fn==="function"?fn(prev):fn;saveData("data",next);return next})},[]);const upUsers=useCallback(fn=>{setUsers(prev=>{const next=typeof fn==="function"?fn(prev):fn;saveData("users",next);return next})},[]);
const kpis=computeKpis(data,period);const isAdmin=user?.role==="admin";const ed=canEdit(user);const apo=isApoiador(user);
const visibleTabs=getVisibleTabs(user);const visibleIcons=getVisibleIcons(user);
if(loading)return(<div style={{background:"#0D1117",minHeight:"100vh",display:"flex",alignItems:"center",justifyContent:"center",color:"#F5A623",fontFamily:"'Outfit',sans-serif",fontSize:20}}>Carregando NEMPA Hub...</div>);
if(!user)return <LoginScreen onLogin={setUser} users={users}/>;const curTab=visibleTabs[tab]||"Dashboard";const rc=ROLE_COLORS_FN(T);
return(<ThemeCtx.Provider value={T}><UserCtx.Provider value={user}><div style={{background:T.bg,minHeight:"100vh",fontFamily:"'Outfit',sans-serif",color:T.text}}>
<header style={{background:T.headerBg,borderBottom:"1px solid "+T.border,padding:"8px 20px",display:"flex",alignItems:"center",gap:12,position:"sticky",top:0,zIndex:100,flexWrap:"wrap"}}><NempaLogo size={36}/><div style={{fontSize:10,color:T.textMuted,letterSpacing:.5,marginRight:"auto"}}>Núcleo de Empreendedorismo<br/>de Pouso Alegre</div><div style={{fontSize:12,color:T.yellow,fontWeight:600,whiteSpace:"nowrap"}}>📅 {curDate()}</div><div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap"}}><span style={{fontSize:12,color:T.textMuted}}>👤 {user.nome}</span><span style={{fontSize:10,background:(rc[user.role]||T.textMuted)+"33",color:rc[user.role]||T.textMuted,padding:"2px 8px",borderRadius:10,fontWeight:700}}>{ROLE_LABELS[user.role]}</span><button onClick={()=>setTheme(t=>t==="dark"?"light":"dark")} style={{background:T.border,border:"none",borderRadius:20,padding:"5px 12px",cursor:"pointer",fontSize:13,color:T.text,fontFamily:"'Outfit',sans-serif",fontWeight:600}}>{theme==="dark"?"☀️":"🌙"}</button><button onClick={()=>{setUser(null);setTab(0)}} style={{background:T.red+"33",color:T.red,border:"none",borderRadius:20,padding:"5px 12px",cursor:"pointer",fontSize:12,fontWeight:700,fontFamily:"'Outfit',sans-serif"}}>Sair</button></div></header>
<nav style={{display:"flex",gap:2,padding:"6px 20px",overflowX:"auto",borderBottom:"1px solid "+T.border,background:T.card}}>{visibleTabs.map((t,i)=>(<button key={t} onClick={()=>setTab(i)} style={{background:tab===i?T.yellow+"22":"transparent",color:tab===i?T.yellow:T.textMuted,border:"none",borderRadius:10,padding:"8px 14px",fontSize:13,fontWeight:700,cursor:"pointer",fontFamily:"'Outfit',sans-serif",whiteSpace:"nowrap"}}>{visibleIcons[i]} {t}</button>))}</nav>
<main style={{maxWidth:1100,margin:"0 auto",padding:"24px 20px"}}>
{curTab==="Dashboard"&&(apo?<DashApoiador kpis={kpis}/>:<DashTab kpis={kpis} data={data} period={period} setPeriod={setPeriod}/>)}
{curTab==="Ações"&&<AcoesTab data={data} up={up} openModal={openModal}/>}
{curTab==="Relatórios"&&<ReportsTab data={data} up={up} openModal={openModal}/>}
{curTab==="Comparativo"&&<ComparativoTab data={data}/>}
{curTab==="Calendário"&&<CalendarTab data={data} up={up} openModal={openModal}/>}
{curTab==="Associados"&&<AssociadosTab data={data} up={up} openModal={openModal}/>}
{curTab==="Parceiros"&&<ParceirosTab data={data} up={up} openModal={openModal}/>}
{curTab==="Documentos"&&<DocumentosTab data={data} up={up} openModal={openModal}/>}
{curTab==="Leads"&&<LeadsTab data={data} up={up} openModal={openModal}/>}
{curTab==="Usuários"&&isAdmin&&<UsersTab users={users} upUsers={upUsers}/>}
</main>
{ed&&<><AcaoModal open={modal?.type==="acao"} onClose={closeModal} up={up} editItem={modal?.edit}/><ReportModal open={modal?.type==="report"} onClose={closeModal} up={up} data={data} editItem={modal?.edit}/><EventoModal open={modal?.type==="evento"} onClose={closeModal} up={up} editItem={modal?.edit}/><AssociadoModal open={modal?.type==="associado"} onClose={closeModal} up={up} editItem={modal?.edit}/><ParceiroModal open={modal?.type==="parceiro"} onClose={closeModal} up={up} editItem={modal?.edit}/><DocModal open={modal?.type==="doc"} onClose={closeModal} up={up} editItem={modal?.edit}/><LeadModal open={modal?.type==="lead"} onClose={closeModal} up={up} editItem={modal?.edit}/></>}
</div></UserCtx.Provider></ThemeCtx.Provider>)}

// ── DASHBOARD APOIADOR ──
function DashApoiador({kpis}){const T=useContext(ThemeCtx);return(<div><div style={{marginBottom:18}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>Painel do Apoiador</h2><p style={{color:T.textMuted,fontSize:13,marginTop:4}}>Visão geral das atividades do NEMPA</p></div><div style={{display:"flex",flexWrap:"wrap",gap:12,marginBottom:24}}><StatCard icon="⚡" label="Ações" value={kpis.totalAcoes} accent={T.yellow}/><StatCard icon="👥" label="Pessoas impactadas" value={kpis.pessoasImpactadas.toLocaleString("pt-BR")} accent={T.blue}/><StatCard icon="⏱️" label="Horas de atividades" value={kpis.horasTotais+"h"} accent={T.yellow}/><StatCard icon="🔄" label="Atividades externas" value={kpis.externas} accent={T.orange}/><StatCard icon="🤝" label="Parceiros ativos" value={kpis.parceiros} accent={T.red}/><StatCard icon="🎫" label="Associados" value={kpis.associados} accent={T.yellow}/><StatCard icon="🎯" label="Leads cadastrados" value={kpis.leads} accent={T.purple}/></div><div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22,textAlign:"center",color:T.textMuted}}><p style={{fontSize:14,margin:0}}>📊 Navegue pelas abas <strong style={{color:T.yellow}}>Ações</strong>, <strong style={{color:T.blue}}>Relatórios</strong> e <strong style={{color:T.success}}>Comparativo</strong> para mais detalhes.</p></div></div>)}

// ── DASHBOARD COMPLETO ──
function DashTab({kpis,data,period,setPeriod}){const T=useContext(ThemeCtx);const summary=monthly(data,period||365);return(<div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>Painel de KPIs</h2><div style={{display:"flex",gap:4,alignItems:"center"}}><Btn small outline={period!==null} onClick={()=>setPeriod(null)} style={{opacity:period===null?1:.45}}>Tudo</Btn>{PERIOD_OPTIONS.map(p=>(<Btn key={p.days} small outline={period!==p.days} onClick={()=>setPeriod(p.days)} style={{opacity:period===p.days?1:.45}}>{p.label}</Btn>))}</div></div><div style={{display:"flex",flexWrap:"wrap",gap:12,marginBottom:24}}><StatCard icon="⚡" label="Ações" value={kpis.totalAcoes} accent={T.yellow}/><StatCard icon="👥" label="Pessoas impactadas" value={kpis.pessoasImpactadas.toLocaleString("pt-BR")} accent={T.blue}/><StatCard icon="⏱️" label="Horas de atividades" value={kpis.horasTotais+"h"} accent={T.yellow}/><StatCard icon="💰" label="Custo das ações" value={fc(kpis.custoTotal)} accent={T.red}/><StatCard icon="🔄" label="Atividades externas" value={kpis.externas} accent={T.orange}/><StatCard icon="🤝" label="Parceiros ativos" value={kpis.parceiros} sub={kpis.cotaParceiros>0?fc(kpis.cotaParceiros)+"/mês":null} accent={T.red}/><StatCard icon="🎫" label="Associados" value={kpis.associados} sub={kpis.cotaAssociados>0?fc(kpis.cotaAssociados)+"/mês":null} accent={T.yellow}/><StatCard icon="🎯" label="Leads cadastrados" value={kpis.leads} accent={T.purple}/></div>{summary.length>0&&<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22,marginBottom:20}}><h3 style={{margin:"0 0 14px",fontSize:16,fontWeight:700}}>📈 Relatório Mensal</h3><div style={{display:"flex",alignItems:"flex-end",gap:8,height:150,marginBottom:18,overflowX:"auto"}}>{summary.map(m=>{const mx=Math.max(...summary.map(x=>x.pessoas||1));const h=Math.max((m.pessoas/mx)*130,5);return(<div key={m.key} style={{display:"flex",flexDirection:"column",alignItems:"center",flex:"1 1 50px",minWidth:44}}><div style={{fontSize:11,color:T.textMuted,marginBottom:3}}>{m.pessoas}</div><div style={{width:"100%",maxWidth:40,height:h,borderRadius:"6px 6px 0 0",background:"linear-gradient(180deg,"+T.yellow+","+T.red+")"}}/><div style={{fontSize:10,color:T.textMuted,marginTop:5,textAlign:"center"}}>{m.label}</div></div>)})}</div><div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:13}}><thead><tr style={{borderBottom:"2px solid "+T.border}}>{["Mês","Ações","Pessoas","Custo","Horas"].map(h=>(<th key={h} style={{textAlign:"left",padding:"7px 10px",color:T.textMuted,fontWeight:700,fontSize:12}}>{h}</th>))}</tr></thead><tbody>{summary.map(m=>(<tr key={m.key} style={{borderBottom:"1px solid "+T.border}}><td style={{padding:"7px 10px",fontWeight:600}}>{m.label}</td><td style={{padding:"7px 10px"}}>{m.acoes}</td><td style={{padding:"7px 10px"}}>{m.pessoas.toLocaleString("pt-BR")}</td><td style={{padding:"7px 10px"}}>{fc(m.custo)}</td><td style={{padding:"7px 10px"}}>{m.horas}h</td></tr>))}<tr style={{fontWeight:800,color:T.yellow}}><td style={{padding:"7px 10px"}}>Total</td><td style={{padding:"7px 10px"}}>{summary.reduce((s,m)=>s+m.acoes,0)}</td><td style={{padding:"7px 10px"}}>{summary.reduce((s,m)=>s+m.pessoas,0).toLocaleString("pt-BR")}</td><td style={{padding:"7px 10px"}}>{fc(summary.reduce((s,m)=>s+m.custo,0))}</td><td style={{padding:"7px 10px"}}>{summary.reduce((s,m)=>s+m.horas,0)}h</td></tr></tbody></table></div></div>}<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22}}><h3 style={{margin:"0 0 12px",fontSize:16,fontWeight:700}}>Últimas Ações</h3>{(data.acoes||[]).length===0?<p style={{color:T.textMuted,fontSize:14}}>Nenhuma ação.</p>:(data.acoes||[]).slice(-5).reverse().map(a=>(<div key={a.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"9px 0",borderBottom:"1px solid "+T.border,flexWrap:"wrap",gap:6}}><div><div style={{fontWeight:700,fontSize:14}}>{a.nome}</div><div style={{fontSize:12,color:T.textMuted}}>{fd(a.data)}{a.iniciativa?" · "+a.iniciativa:""}</div></div><div style={{display:"flex",gap:6}}><Badge color={T.blue}>{a.pessoas} pessoas</Badge><Badge color={T.yellow}>{a.horas}h</Badge></div></div>))}</div></div>)}

// ── COMPARATIVO ──
function ComparativoTab({data}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const apo=isApoiador(user);
const[p1Start,setP1Start]=useState("");const[p1End,setP1End]=useState("");const[p2Start,setP2Start]=useState("");const[p2End,setP2End]=useState("");const[result,setResult]=useState(null);
const compare=()=>{if(!p1Start||!p1End||!p2Start||!p2End)return;const r1=computeRange(data,p1Start,p1End);const r2=computeRange(data,p2Start,p2End);setResult({r1,r2})};
const metrics=apo?[{k:"totalAcoes",label:"Ações",icon:"⚡"},{k:"pessoasImpactadas",label:"Pessoas impactadas",icon:"👥"},{k:"horasTotais",label:"Horas de atividades",icon:"⏱️"},{k:"externas",label:"Atividades externas",icon:"🔄"}]:[{k:"totalAcoes",label:"Ações",icon:"⚡"},{k:"pessoasImpactadas",label:"Pessoas impactadas",icon:"👥"},{k:"horasTotais",label:"Horas de atividades",icon:"⏱️"},{k:"custoTotal",label:"Custo das ações",icon:"💰",fmt:true},{k:"externas",label:"Atividades externas",icon:"🔄"}];
const fmtVal=(v,fmt)=>fmt?fc(v):v.toLocaleString("pt-BR");
const pct=(a,b)=>{if(b===0)return a>0?"+100%":"0%";const d=((a-b)/b*100).toFixed(0);return (d>0?"+":"")+d+"%"};
return(<div><h2 style={{margin:"0 0 18px",fontSize:22,fontWeight:800}}>📈 Comparativo de Períodos</h2>
<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22,marginBottom:20}}>
<div style={{display:"flex",gap:20,flexWrap:"wrap",marginBottom:16}}>
<div style={{flex:1,minWidth:200}}><h4 style={{margin:"0 0 8px",color:T.yellow,fontSize:14}}>📅 Período 1</h4><div style={{display:"flex",gap:8}}><Inp label="De" type="date" value={p1Start} onChange={e=>setP1Start(e.target.value)}/><Inp label="Até" type="date" value={p1End} onChange={e=>setP1End(e.target.value)}/></div></div>
<div style={{flex:1,minWidth:200}}><h4 style={{margin:"0 0 8px",color:T.blue,fontSize:14}}>📅 Período 2</h4><div style={{display:"flex",gap:8}}><Inp label="De" type="date" value={p2Start} onChange={e=>setP2Start(e.target.value)}/><Inp label="Até" type="date" value={p2End} onChange={e=>setP2End(e.target.value)}/></div></div>
</div>
<Btn onClick={compare} disabled={!p1Start||!p1End||!p2Start||!p2End}>Comparar Períodos</Btn>
</div>
{result&&<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22}}>
<h3 style={{margin:"0 0 16px",fontSize:16,fontWeight:700}}>Resultado da Comparação</h3>
<div style={{overflowX:"auto"}}><table style={{width:"100%",borderCollapse:"collapse",fontSize:14}}>
<thead><tr style={{borderBottom:"2px solid "+T.border}}><th style={{textAlign:"left",padding:"10px 12px",color:T.textMuted,fontSize:12}}>Métrica</th><th style={{textAlign:"center",padding:"10px 12px",color:T.yellow,fontSize:12}}>Período 1<br/><span style={{fontWeight:400}}>{fd(p1Start)} a {fd(p1End)}</span></th><th style={{textAlign:"center",padding:"10px 12px",color:T.blue,fontSize:12}}>Período 2<br/><span style={{fontWeight:400}}>{fd(p2Start)} a {fd(p2End)}</span></th><th style={{textAlign:"center",padding:"10px 12px",color:T.textMuted,fontSize:12}}>Variação</th></tr></thead>
<tbody>{metrics.map(m=>{const v1=result.r1[m.k]||0;const v2=result.r2[m.k]||0;const diff=v2-v1;const color=diff>0?T.success:diff<0?T.red:T.textMuted;return(<tr key={m.k} style={{borderBottom:"1px solid "+T.border}}><td style={{padding:"12px",fontWeight:600}}>{m.icon} {m.label}</td><td style={{padding:"12px",textAlign:"center",fontSize:20,fontWeight:800}}>{fmtVal(v1,m.fmt)}</td><td style={{padding:"12px",textAlign:"center",fontSize:20,fontWeight:800}}>{fmtVal(v2,m.fmt)}</td><td style={{padding:"12px",textAlign:"center",fontWeight:700,color}}>{pct(v2,v1)}</td></tr>)})}</tbody>
</table></div>
{/* Visual bars */}
<div style={{marginTop:20}}>{metrics.map(m=>{const v1=result.r1[m.k]||0;const v2=result.r2[m.k]||0;const mx=Math.max(v1,v2,1);return(<div key={m.k} style={{marginBottom:12}}><div style={{fontSize:12,color:T.textMuted,marginBottom:4}}>{m.icon} {m.label}</div><div style={{display:"flex",gap:6,alignItems:"center"}}><div style={{flex:1}}><div style={{height:20,borderRadius:6,background:T.yellow+"44",width:Math.max((v1/mx)*100,2)+"%",display:"flex",alignItems:"center",paddingLeft:6,fontSize:11,fontWeight:700,color:T.yellow}}>{m.fmt?fc(v1):v1}</div></div><div style={{flex:1}}><div style={{height:20,borderRadius:6,background:T.blue+"44",width:Math.max((v2/mx)*100,2)+"%",display:"flex",alignItems:"center",paddingLeft:6,fontSize:11,fontWeight:700,color:T.blue}}>{m.fmt?fc(v2):v2}</div></div></div></div>)})}</div>
</div>}
</div>)}

// ── AÇÕES ──
function AcoesTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,acoes:p.acoes.filter(a=>a.id!==id)}));return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>Gestão de Ações</h2>{ed&&<Btn onClick={()=>openModal("acao")}>＋ Nova Ação</Btn>}</div>{(data.acoes||[]).length===0?<p style={{color:T.textMuted}}>Nenhuma ação.</p>:<div style={{display:"flex",flexDirection:"column",gap:10}}>{data.acoes.map(a=>(<div key={a.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:14,padding:"14px 18px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:10}}><div style={{flex:1,minWidth:200}}><div style={{fontWeight:700,fontSize:15}}>{a.nome}</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>{fd(a.data)} · Equipe: {a.equipe}</div>{a.iniciativa&&<div style={{fontSize:12,color:a.iniciativa==="Iniciativa de terceiros"?T.orange:T.success,marginTop:2}}>{a.iniciativa==="Iniciativa de terceiros"?"🔄":"✅"} {a.iniciativa}</div>}{a.descricao&&<div style={{fontSize:13,color:T.textMuted,marginTop:5}}>{a.descricao}</div>}{a.fotoUrl&&<img src={a.fotoUrl} alt={a.nome} style={{marginTop:8,maxWidth:"100%",maxHeight:200,borderRadius:10,objectFit:"cover",border:"1px solid "+T.border}}/>}</div><div style={{display:"flex",gap:6,flexWrap:"wrap",alignItems:"center"}}><Badge color={T.blue}>{a.pessoas} pessoas</Badge><Badge color={T.red}>{fc(a.custo)}</Badge><Badge color={T.yellow}>{a.horas}h</Badge>{ed&&<><span onClick={()=>openModal("acao",a)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(a.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}</div>)}

function ReportsTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,reports:p.reports.filter(r=>r.id!==id)}));return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>Relatórios</h2>{ed&&<Btn onClick={()=>openModal("report")} accent={T.blue}>＋ Novo</Btn>}</div>{(data.reports||[]).length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum relatório.</div>:<div style={{display:"flex",flexDirection:"column",gap:12}}>{data.reports.slice().reverse().map(r=>(<div key={r.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:20}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}><div><Badge color={T.yellow}>{r.acao}</Badge><div style={{fontSize:13,color:T.textMuted,marginTop:6}}><strong style={{color:T.text}}>{r.autor}</strong> · {fd(r.data)}</div></div>{ed&&<div style={{display:"flex",gap:6}}><span onClick={()=>openModal("report",r)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(r.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></div>}</div><p style={{fontSize:14,lineHeight:1.6,color:T.text,marginTop:10,whiteSpace:"pre-wrap"}}>{r.texto}</p></div>))}</div>}</div>)}

function CalendarTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const[mo,setMo]=useState(()=>{const d=new Date();return{y:d.getFullYear(),m:d.getMonth()}});const fd1=new Date(mo.y,mo.m,1).getDay();const dim=new Date(mo.y,mo.m+1,0).getDate();const cells=[];for(let i=0;i<fd1;i++)cells.push(null);for(let d=1;d<=dim;d++)cells.push(d);const all=[...(data.acoes||[]).map(a=>({...a,type:"acao"})),...(data.eventos||[]).map(e=>({...e,type:"evento"}))];const onDay=day=>{const ds=mo.y+"-"+String(mo.m+1).padStart(2,"0")+"-"+String(day).padStart(2,"0");return all.filter(e=>e.data===ds)};const rmEv=id=>up(p=>({...p,eventos:(p.eventos||[]).filter(e=>e.id!==id)}));const prev=()=>setMo(p=>p.m===0?{y:p.y-1,m:11}:{y:p.y,m:p.m-1});const next=()=>setMo(p=>p.m===11?{y:p.y+1,m:0}:{y:p.y,m:p.m+1});const MS=["Janeiro","Fevereiro","Março","Abril","Maio","Junho","Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"];const tc={acao:T.yellow,evento:T.success};const tl={acao:"NEMPA",evento:"Evento"};const future=all.filter(e=>e.data>=today()).sort((a,b)=>a.data.localeCompare(b.data));return(<div><div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>Calendário</h2><div style={{display:"flex",gap:8,alignItems:"center"}}>{ed&&<Btn onClick={()=>openModal("evento")} accent={T.success}>＋ Evento</Btn>}<Btn small outline onClick={prev}>◀</Btn><span style={{fontWeight:700,fontSize:15,minWidth:150,textAlign:"center"}}>{MS[mo.m]} {mo.y}</span><Btn small outline onClick={next}>▶</Btn></div></div><div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:18,overflowX:"auto"}}><div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:3,minWidth:480}}>{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map(d=>(<div key={d} style={{textAlign:"center",fontSize:11,fontWeight:700,color:T.textMuted,padding:"5px 0"}}>{d}</div>))}{cells.map((day,i)=>{const ev=day?onDay(day):[];const isT=day&&mo.y===new Date().getFullYear()&&mo.m===new Date().getMonth()&&day===new Date().getDate();return(<div key={i} style={{minHeight:68,background:isT?T.yellow+"15":T.bg,border:isT?"1px solid "+T.yellow+"44":"1px solid "+T.border,borderRadius:8,padding:5}}>{day&&<><div style={{fontSize:12,fontWeight:isT?800:400,color:isT?T.yellow:T.textMuted}}>{day}</div>{ev.map(e=>(<div key={e.id} style={{fontSize:9,background:(tc[e.type]||T.yellow)+"33",color:tc[e.type]||T.yellow,borderRadius:3,padding:"1px 4px",marginTop:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",fontWeight:600}}>{e.nome}</div>))}</>}</div>)})}</div></div><div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:20,marginTop:16}}><h3 style={{margin:"0 0 12px",fontSize:16,fontWeight:700}}>🗓️ Próximos Eventos</h3>{future.length===0?<p style={{color:T.textMuted,fontSize:14}}>Nenhum evento futuro.</p>:future.slice(0,10).map(e=>(<div key={e.id} style={{display:"flex",justifyContent:"space-between",padding:"8px 0",borderBottom:"1px solid "+T.border,alignItems:"center",flexWrap:"wrap",gap:6}}><div><span style={{fontWeight:600,fontSize:14}}>{e.nome}</span>{e.hora&&<span style={{fontSize:11,color:T.textMuted}}> · 🕐 {e.hora}</span>}</div><div style={{display:"flex",gap:6,alignItems:"center"}}><Badge color={tc[e.type]}>{tl[e.type]}</Badge><span style={{fontSize:12,color:T.textMuted}}>{fd(e.data)}</span>{e.type==="evento"&&ed&&<><span onClick={()=>openModal("evento",e)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rmEv(e.id)} style={{cursor:"pointer",color:T.textMuted,fontSize:14}}>🗑️</span></>}</div></div>))}</div></div>)}

function AssociadosTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,associados:(p.associados||[]).filter(a=>a.id!==id)}));const total=(data.associados||[]).reduce((s,a)=>s+(Number(a.cota)||0),0);return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>🎫 Associados ({(data.associados||[]).length})</h2><div style={{display:"flex",gap:8,alignItems:"center"}}><span style={{fontSize:13,color:T.yellow,fontWeight:700}}>Cotas: {fc(total)}/mês</span>{ed&&<Btn onClick={()=>openModal("associado")}>＋ Novo</Btn>}</div></div>{(data.associados||[]).length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum associado.</div>:<div style={{display:"flex",flexDirection:"column",gap:10}}>{(data.associados||[]).map(a=>(<div key={a.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:14,padding:"16px 20px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}><div style={{flex:1,minWidth:220}}><div style={{fontWeight:700,fontSize:16}}>{a.nome}</div><div style={{fontSize:12,color:T.textMuted,marginTop:4}}>{a.cpfCnpj&&<span>{a.cpfCnpj} · </span>}{a.email}{a.telefone?" · "+a.telefone:""}</div>{a.empresa&&<div style={{fontSize:12,color:T.textMuted,marginTop:2}}>🏢 {a.empresa}</div>}</div><div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}>{a.cota&&Number(a.cota)>0&&<Badge color={T.success}>{fc(Number(a.cota))}/mês</Badge>}{a.status&&<Badge color={a.status==="Ativo"?T.success:T.red}>{a.status}</Badge>}<Badge color={T.yellow}>Desde {fd(a.data)}</Badge>{ed&&<><span onClick={()=>openModal("associado",a)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(a.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}</div>)}

function ParceirosTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,parceiros:(p.parceiros||[]).filter(a=>a.id!==id)}));const total=(data.parceiros||[]).reduce((s,p)=>s+(Number(p.cotaApoio)||0),0);return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>🤝 Parceiros ({(data.parceiros||[]).length})</h2><div style={{display:"flex",gap:8,alignItems:"center"}}><span style={{fontSize:13,color:T.blue,fontWeight:700}}>Apoio: {fc(total)}/mês</span>{ed&&<Btn onClick={()=>openModal("parceiro")} accent={T.blue}>＋ Novo</Btn>}</div></div>{(data.parceiros||[]).length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum parceiro.</div>:<div style={{display:"flex",flexDirection:"column",gap:10}}>{(data.parceiros||[]).map(p=>(<div key={p.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:14,padding:"16px 20px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}><div style={{flex:1,minWidth:220}}><div style={{fontWeight:700,fontSize:16}}>{p.nome}</div>{p.nomeContato&&<div style={{fontSize:12,color:T.textMuted,marginTop:3}}>👤 {p.nomeContato}</div>}<div style={{fontSize:12,color:T.textMuted,marginTop:2}}>{p.cpfCnpj&&<span>{p.cpfCnpj} · </span>}{p.email}{p.telefone?" · "+p.telefone:""}</div></div><div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}><Badge color={T.blue}>{p.tipo}</Badge>{p.cotaApoio&&Number(p.cotaApoio)>0&&<Badge color={T.success}>{fc(Number(p.cotaApoio))}/mês</Badge>}{p.status&&<Badge color={p.status==="Ativo"?T.success:T.red}>{p.status}</Badge>}{ed&&<><span onClick={()=>openModal("parceiro",p)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(p.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}</div>)}

function DocumentosTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,documentos:(p.documentos||[]).filter(d=>d.id!==id)}));const docs=data.documentos||[];const cats=[...new Set(docs.map(d=>d.categoria).filter(Boolean))];const[filtro,setFiltro]=useState("");const filtered=filtro?docs.filter(d=>d.categoria===filtro):docs;const ci={"Ata":"📋","Contrato":"📑","Financeiro":"💰","Planejamento":"📐","Comunicação":"📣","Jurídico":"⚖️","Outro":"📄"};return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>📁 Documentos ({docs.length})</h2>{ed&&<Btn onClick={()=>openModal("doc")} accent={T.orange}>＋ Novo</Btn>}</div>{cats.length>0&&<div style={{display:"flex",gap:4,marginBottom:14,flexWrap:"wrap"}}><Btn small outline={filtro!==""} onClick={()=>setFiltro("")} style={{opacity:filtro===""?1:.45}}>Todos</Btn>{cats.map(c=>(<Btn key={c} small outline={filtro!==c} onClick={()=>setFiltro(c)} style={{opacity:filtro===c?1:.45}}>{ci[c]||"📄"} {c}</Btn>))}</div>}{filtered.length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum documento.</div>:<div style={{display:"flex",flexDirection:"column",gap:10}}>{filtered.slice().reverse().map(d=>(<div key={d.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:14,padding:"16px 20px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}><div style={{flex:1,minWidth:220}}><div style={{display:"flex",gap:8,alignItems:"center"}}><span style={{fontSize:22}}>{ci[d.categoria]||"📄"}</span><div><div style={{fontWeight:700,fontSize:15}}>{d.titulo}</div><div style={{fontSize:12,color:T.textMuted}}>{d.categoria} · {fd(d.data)}</div></div></div>{d.descricao&&<div style={{fontSize:13,color:T.textMuted,marginTop:6}}>{d.descricao}</div>}{d.link&&<a href={d.link} target="_blank" rel="noopener noreferrer" style={{color:T.blue,fontSize:13,marginTop:6,display:"inline-block"}}>🔗 Abrir link</a>}</div><div style={{display:"flex",gap:6,alignItems:"center"}}><Badge color={T.orange}>{d.categoria}</Badge>{ed&&<><span onClick={()=>openModal("doc",d)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(d.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}</div>)}

function LeadsTab({data,up,openModal}){const T=useContext(ThemeCtx);const user=useContext(UserCtx);const ed=canEdit(user);const rm=id=>up(p=>({...p,leads:(p.leads||[]).filter(l=>l.id!==id)}));const leads=data.leads||[];const sc={"Novo":T.blue,"Em contato":T.yellow,"Proposta enviada":T.orange,"Negociando":T.purple,"Fechado":T.success,"Perdido":T.red};const[fs,setFs]=useState("");const filtered=fs?leads.filter(l=>l.status===fs):leads;const sts=["Novo","Em contato","Proposta enviada","Negociando","Fechado","Perdido"];return(<div>{!ed&&<ReadOnlyBanner/>}<div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18,flexWrap:"wrap",gap:8}}><h2 style={{margin:0,fontSize:22,fontWeight:800}}>🎯 Leads ({leads.length})</h2>{ed&&<Btn onClick={()=>openModal("lead")} accent={T.purple}>＋ Novo Lead</Btn>}</div><div style={{display:"flex",gap:6,marginBottom:16,flexWrap:"wrap"}}><Btn small outline={fs!==""} onClick={()=>setFs("")} style={{opacity:fs===""?1:.45}}>Todos ({leads.length})</Btn>{sts.map(st=>{const ct=leads.filter(l=>l.status===st).length;return ct>0?(<Btn key={st} small outline={fs!==st} accent={sc[st]} onClick={()=>setFs(st)} style={{opacity:fs===st?1:.45}}>{st} ({ct})</Btn>):null})}</div>{filtered.length===0?<div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:36,textAlign:"center",color:T.textMuted}}>Nenhum lead.</div>:<div style={{display:"flex",flexDirection:"column",gap:10}}>{filtered.slice().reverse().map(l=>(<div key={l.id} style={{background:T.card,border:"1px solid "+T.border,borderRadius:14,padding:"16px 20px"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:8}}><div style={{flex:1,minWidth:220}}><div style={{fontWeight:700,fontSize:16}}>{l.empresa}</div><div style={{fontSize:12,color:T.textMuted,marginTop:3}}>👤 {l.contato}{l.email?" · "+l.email:""}{l.telefone?" · "+l.telefone:""}</div><div style={{fontSize:12,color:T.textMuted,marginTop:2}}>📅 {fd(l.data)} · {l.abordagem}</div>{l.retorno&&<div style={{fontSize:12,color:T.success,marginTop:2}}>🔄 Retorno: {fd(l.retorno)}</div>}{l.notas&&<div style={{fontSize:13,color:T.textMuted,marginTop:6,fontStyle:"italic"}}>{l.notas}</div>}</div><div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}><Badge color={sc[l.status]||T.textMuted}>{l.status}</Badge>{ed&&<><span onClick={()=>openModal("lead",l)} style={{cursor:"pointer",color:T.blue,fontSize:14}}>✏️</span><span onClick={()=>rm(l.id)} style={{cursor:"pointer",color:T.textMuted}}>🗑️</span></>}</div></div></div>))}</div>}</div>)}

function UsersTab({users,upUsers}){const T=useContext(ThemeCtx);const[f,sF]=useState({nome:"",login:"",senha:"",role:"editor"});const[msg,setMsg]=useState("");const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const roleOpts=[{value:"admin",label:"Administrador"},{value:"editor",label:"Editor"},{value:"leitor",label:"Leitor"},{value:"apoiador",label:"Apoiador"}];const add=()=>{if(!f.nome||!f.login||!f.senha){setMsg("Preencha todos os campos.");return}if(users.find(u=>u.login===f.login)){setMsg("Login já existe.");return}upUsers(prev=>[...prev,{...f,id:gid(),senha:hashPw(f.senha)}]);sF({nome:"",login:"",senha:"",role:"editor"});setMsg("Usuário criado!");setTimeout(()=>setMsg(""),3000)};const rm=id=>{if(id==="admin")return;upUsers(prev=>prev.filter(u=>u.id!==id))};const resetPw=id=>{const pw=prompt("Nova senha:");if(!pw)return;upUsers(prev=>prev.map(u=>u.id===id?{...u,senha:hashPw(pw)}:u))};const changeRole=(id,role)=>{if(id==="admin")return;upUsers(prev=>prev.map(u=>u.id===id?{...u,role}:u))};const rc=ROLE_COLORS_FN(T);return(<div><h2 style={{margin:"0 0 18px",fontSize:22,fontWeight:800}}>🔐 Gestão de Usuários</h2><div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22,marginBottom:20}}><h3 style={{margin:"0 0 14px",fontSize:16,fontWeight:700}}>Adicionar Usuário</h3><div style={{display:"flex",flexDirection:"column",gap:12}}><div style={{display:"flex",gap:10,flexWrap:"wrap"}}><Inp label="Nome *" value={f.nome} onChange={s("nome")}/><Inp label="Login *" value={f.login} onChange={s("login")}/></div><div style={{display:"flex",gap:10,flexWrap:"wrap"}}><Inp label="Senha *" value={f.senha} onChange={s("senha")}/><Sel label="Perfil" value={f.role} onChange={s("role")} options={roleOpts}/></div><div style={{fontSize:12,color:T.textMuted,background:T.bg,borderRadius:8,padding:"10px 14px",border:"1px solid "+T.border,lineHeight:1.8}}>{roleOpts.map(r=>(<div key={r.value}><strong style={{color:rc[r.value]||T.text}}>{r.label}:</strong> {ROLE_DESC[r.value]}</div>))}</div>{msg&&<div style={{fontSize:13,fontWeight:600,color:msg.includes("criado")?T.success:T.red}}>{msg}</div>}<Btn onClick={add} style={{alignSelf:"flex-start"}}>＋ Criar</Btn></div></div><div style={{background:T.card,border:"1px solid "+T.border,borderRadius:16,padding:22}}><h3 style={{margin:"0 0 14px",fontSize:16,fontWeight:700}}>Usuários ({users.length})</h3>{users.map(u=>(<div key={u.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"10px 14px",background:T.bg,borderRadius:12,border:"1px solid "+T.border,marginBottom:8,flexWrap:"wrap",gap:8}}><div><div style={{fontWeight:700,fontSize:14}}>{u.nome}</div><div style={{fontSize:12,color:T.textMuted}}>Login: <strong>{u.login}</strong></div></div><div style={{display:"flex",gap:6,alignItems:"center",flexWrap:"wrap"}}><Badge color={rc[u.role]||T.textMuted}>{ROLE_LABELS[u.role]||u.role}</Badge>{u.id!=="admin"&&<select value={u.role} onChange={e=>changeRole(u.id,e.target.value)} style={{background:T.bg,border:"1px solid "+T.border,borderRadius:8,padding:"3px 8px",color:T.text,fontSize:11,fontFamily:"'Outfit',sans-serif"}}>{roleOpts.map(o=>(<option key={o.value} value={o.value}>{o.label}</option>))}</select>}<button onClick={()=>resetPw(u.id)} style={{background:T.blue+"22",color:T.blue,border:"none",borderRadius:8,padding:"4px 10px",fontSize:11,fontWeight:700,cursor:"pointer",fontFamily:"'Outfit',sans-serif"}}>Resetar</button>{u.id!=="admin"&&<span onClick={()=>rm(u.id)} style={{cursor:"pointer",color:T.textMuted,fontSize:14}}>🗑️</span>}</div></div>))}</div></div>)}

