function AcaoModal({open,onClose,up,editItem}){const T=useContext(ThemeCtx);const blank={nome:"",data:"",pessoas:"",custo:"",horas:"",equipe:"",territorio:"",descricao:"",iniciativa:"Iniciativa própria",fotoUrl:""};const[f,sF]=useState(blank);const s=k=>e=>sF(p=>({...p,[k]:e.target.value}));const isE=!!editItem;useEffect(()=>{if(open)sF(editItem?{...blank,...editItem,pessoas:String(editItem.pessoas||""),custo:String(editItem.custo||""),horas:String(editItem.horas||"")}:blank)},[open,editItem]);const go=()=>{if(!f.nome||!f.data)return;const item={...f,pessoas:Number(f.pessoas)||0,custo:Number(f.custo)||0,horas:Number(f.horas)||0};if(isE)up(p=>({...p,acoes:p.acoes.map(a=>a.id===editItem.id?{...a,...item}:a)}));else up(p=>({...p,acoes:[...p.acoes,{...item,id:gid()}]}));onClose()};return(<Modal open={open} onClose={onClose} title={isE?"Editar Ação":"Nova Ação"}><div style={{display:"flex",flexDirection:"column",gap:12}}><Inp label="Nome *" value={f.nome} onChange={s("nome")}/><div style={{display:"flex",gap:10}}><Inp label="Data *" type="date" value={f.data} onChange={s("data")}/><Sel label="Tipo de Iniciativa" value={f.iniciativa} onChange={s("iniciativa")} options={INICIATIVA_OPTS}/></div><div style={{display:"flex",gap:10}}><Inp label="Pessoas impactadas" type="number" value={f.pessoas} onChange={s("pessoas")}/><Inp label="Horas" type="number" value={f.horas} onChange={s("horas")}/></div><div style={{display:"flex",gap:10}}><Inp label="Custo (R$)" type="number" value={f.custo} onChange={s("custo")}/><Inp label="Equipe" value={f.equipe} onChange={s("equipe")}/></div><Inp label="Território" value={f.territorio} onChange={s("territorio")}/><Txt label="Descrição" value={f.descricao} onChange={s("descricao")}/><Inp label="📷 URL da foto (cole o link da imagem)" value={f.fotoUrl} onChange={s("fotoUrl")} placeholder="https://drive.google.com/... ou link direto da imagem"/>{f.fotoUrl&&<img src={f.fotoUrl} alt="Preview" style={{maxHeight:120,borderRadius:8,objectFit:"cover"}} onError={e=>{e.target.style.display="none"}}/>}<Btn onClick={go}>{isE?"Atualizar":"Salvar"}</Btn></div></Modal>)}

